CREATE SCHEMA Sales;

CREATE TABLE Sales.Orders
(
    ORDERNUMBER INT,
    QUANTITYORDERED INT,
    PRICEEACH FLOAT,
    ORDERLINENUMBER INT,
    SALES FLOAT,
    ORDERDATE VARCHAR(50),
    STATUS VARCHAR(50),
    QTR_ID INT,
    MONTH_ID INT,
    YEAR_ID INT
);

Drop table Sales.;

COPY INTO Sales.Orders
FROM 'https://adlssaccountak.blob.core.windows.net/synapse-data/synapse/orders_dataset.csv'
WITH (
    FILE_TYPE = 'CSV',
    FIELDTERMINATOR = ',',
    FIELDQUOTE = '"',
    FIRSTROW = 2,
    ENCODING = 'UTF8'
);

SELECT COUNT(*) FROM Sales.Orders;

SELECT TOP 5 * FROM Sales.Orders;
